create or replace function public.create_loan_atomic(p jsonb) returns uuid language plpgsql security definer set search_path=public as $$
declare v_tenant uuid:=(p->>'tenant_id')::uuid;v_client uuid:=(p->>'client_id')::uuid;v_loan uuid:=gen_random_uuid();v_existing uuid;v_user uuid:=auth.uid();v_key text:=p->>'idempotency_key';v_principal numeric(14,2):=(p->>'principal')::numeric;v_interest numeric(14,2):=(p->>'interest_amount')::numeric;v_total numeric(14,2):=(p->>'total_amount')::numeric;v_count int:=jsonb_array_length(p->'installments');v_sum numeric(14,2);v_row jsonb;v_i int:=0;v_date date:=(p->>'start_date')::date;v_expected numeric;begin
 if v_user is null or not public.has_tenant_permission(v_tenant,'loans.create') then raise exception 'not_authorized' using errcode='42501';end if;
 if v_key is null or length(v_key)<12 or length(v_key)>120 then raise exception 'invalid_idempotency_key' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(v_tenant::text||':loan:'||v_key,0));
 select id into v_existing from public.loans where tenant_id=v_tenant and idempotency_key=v_key;if v_existing is not null then return v_existing;end if;
 if v_principal is null or v_interest is null or v_total is null or v_principal::text in ('NaN','Infinity','-Infinity') or v_total::text in ('NaN','Infinity','-Infinity') or v_count is null or v_count>730 or v_date is null or v_date not between date '2000-01-01' and date '2100-01-01' or v_principal<=0 or v_interest<0 or v_total<>v_principal+v_interest or v_count<1 then raise exception 'invalid_terms' using errcode='22023';end if;
 if not exists(select 1 from public.clients where id=v_client and tenant_id=v_tenant and active) then raise exception 'client_not_found' using errcode='22023';end if;
 select coalesce(sum((x->>'amount')::numeric),0) into v_sum from jsonb_array_elements(p->'installments') x;if v_sum<>v_total then raise exception 'installment_total_mismatch' using errcode='22023';end if;
 insert into public.loans(id,tenant_id,client_id,contract_number,modality,state,principal,interest_percent,interest_amount,total_amount,installment_count,installment_amount,start_date,due_day,late_fee,late_fee_block_days,include_sundays,terms_snapshot,created_by,idempotency_key) values(v_loan,v_tenant,v_client,p->>'contract_number',(p->>'modality')::public.loan_modality,'active',v_principal,(p->>'interest_percent')::numeric,v_interest,v_total,v_count,v_total/v_count,(p->>'start_date')::date,nullif(p->>'due_day','')::int,coalesce((p->>'late_fee')::numeric,0),coalesce((p->>'late_fee_block_days')::int,2),coalesce((p->>'include_sundays')::boolean,true),jsonb_build_object('principal',v_principal,'interest_percent',(p->>'interest_percent')::numeric,'interest_amount',v_interest,'total_amount',v_total,'installment_count',v_count,'modality',p->>'modality','start_date',v_date,'late_fee',coalesce((p->>'late_fee')::numeric,0),'late_fee_block_days',coalesce((p->>'late_fee_block_days')::int,2),'include_sundays',coalesce((p->>'include_sundays')::boolean,true)),v_user,v_key);
 for v_row in select value from jsonb_array_elements(p->'installments') loop v_i:=v_i+1;
 if p->>'modality'='monthly' then v_date:=((p->>'start_date')::date+interval '1 month')::date;elsif p->>'modality'='weekly' then v_date:=v_date+7;else v_date:=v_date+1;if not coalesce((p->>'include_sundays')::boolean,true) and extract(dow from v_date)=0 then v_date:=v_date+1;end if;end if;
 v_expected:=(floor(v_total*100/v_count)+case when v_i<=mod(v_total*100,v_count) then 1 else 0 end)/100;
 if (v_row->>'due_date')::date is distinct from v_date or (v_row->>'amount')::numeric is distinct from v_expected then raise exception 'invalid_installment_schedule';end if;
insert into public.installments(tenant_id,loan_id,sequence,due_date,amount) values(v_tenant,v_loan,v_i,(v_row->>'due_date')::date,(v_row->>'amount')::numeric);end loop;
 insert into public.ledger_movements(tenant_id,kind,amount,direction,occurred_at,reference_table,reference_id,description,idempotency_key,created_by) values(v_tenant,'loan_disbursement',v_principal,-1,((p->>'start_date')::date::timestamp at time zone 'America/Sao_Paulo'),'loans',v_loan,'Liberação do contrato '||(p->>'contract_number'),'loan:'||v_loan::text,v_user);
 insert into public.audit_log(tenant_id,actor_id,action,entity,entity_id,metadata) values(v_tenant,v_user,'loan.created','loans',v_loan,jsonb_build_object('principal',v_principal,'installments',v_count));return v_loan;end $$;
